/**
 * 策略參數
 * 定義策略的完整參數組合
 */
export interface StrategyParameters {
  /** 數據源 (close/open/high/low/volume/taker_ratio) */
  data_source: string;
  /** 指標類型 (ema/sma/rsi等) */
  indicator_type: string;
  /** 策略邏輯 (three_line/short_long_cross/mid_long_cross) */
  strategy_logic: string;
  /** EMA短週期參數 */
  ema_short?: number;
  /** EMA中週期參數 */
  ema_mid?: number;
  /** EMA長週期參數 */
  ema_long?: number;
  /** 其他動態參數 */
  [key: string]: unknown;
}

/**
 * 試驗摘要
 * 單個Optuna試驗的完整信息
 */
export interface TrialSummary {
  /** 試驗編號 */
  trial_number: number;
  /** 參數組合 */
  params: StrategyParameters;
  /** 目標值 (separation) */
  value: number;
  /** 試驗狀態 */
  state: 'COMPLETE' | 'PRUNED' | 'FAIL';
  /** 完成時間 */
  datetime_complete: string;
  /** 中間值（用於剪枝分析） */
  intermediate_values?: number[];
  /** 試驗持續時間（單位：秒） */
  duration?: number;
}

/**
 * 參數重要性
 * Optuna計算的參數影響力分析
 */
export interface ParamImportance {
  /** 參數名稱 */
  parameter_name: string;
  /** 重要性得分 (範圍 0-1, 1=最重要) */
  importance: number;
  /** 排名 (1=最重要) */
  rank: number;
}

/**
 * Trial - 單次優化試驗記錄
 * 對應 OptimizationHistoryPoint
 */
export interface Trial {
  /** 試驗編號 */
  trial_number: number;
  /** 目標值 (separation) */
  value: number;
  /** 截至當前的最佳值 */
  best_value_so_far: number;
  /** 完成時間 */
  datetime: string;
  /** 參數組合 */
  params: Record<string, unknown>;
  /** 試驗狀態 */
  state: 'COMPLETE' | 'PRUNED' | 'FAIL';
}

/**
 * 月度數據
 * 按月分組的穩定性分析數據
 */
export interface MonthlyData {
  /** 月份 (YYYY-MM) */
  month: string;
  /** 該月的separation值 */
  separation: number;
  /** 該月的正例平均密度 */
  positive_density: number;
  /** 該月的反例平均密度 */
  negative_density: number;
  /** 該月的案例數量 */
  case_count: number;
}

/**
 * 穩定性分析
 * 策略在不同時期的表現穩定性評估
 */
export interface StabilityAnalysis {
  /** 月度separation數據 */
  monthly_separations: MonthlyData[];
  /** 平均separation */
  mean_separation: number;
  /** separation標準差 */
  std_separation: number;
  /** 變異係數 (CV = std / mean) */
  cv: number;
  /** separation > 0的月份占比 */
  positive_ratio: number;
  /** 表現最差的月份 */
  worst_month: MonthlyData;
  /** 表現最好的月份 */
  best_month: MonthlyData;
}

/**
 * Pareto前沿解
 * 多目標優化中的非支配解
 */
export interface ParetoSolution {
  /** 試驗編號 */
  trial_number: number;
  /** 參數組合 */
  params: StrategyParameters;
  /** 目標1: separation */
  separation: number;
  /** 目標2: 穩定性得分 (1 - CV) */
  stability_score: number;
  /** 是否為推薦解 */
  is_recommended: boolean;
}

/**
 * 優化結果
 * 完整的Optuna優化結果數據
 */
export interface OptimizationResult {
  /** 任務ID */
  task_id: string;
  /** 最佳目標值 (最佳separation) */
  best_value: number;
  /** 最佳參數組合 */
  best_params: StrategyParameters;
  /** 最佳試驗編號 */
  best_trial_number: number;
  /** 總試驗次數 */
  total_trials: number;
  /** 優化總耗時（秒） */
  optimization_time: number;
  /** 收斂歷史（每次試驗的當前最佳值） */
  convergence_history: number[];
  /** 所有試驗摘要 */
  trials_summary: TrialSummary[];
  /** 參數重要性分析 */
  param_importances?: ParamImportance[];
  /** 信號密度分析結果 */
  density_analysis: SignalDensityResponse;
  /** 穩定性分析 */
  stability_analysis?: StabilityAnalysis;
  /** Pareto前沿數據（多目標優化） */
  pareto_front?: ParetoSolution[];
  /** 創建時間 */
  created_at: string;
  /** 完成時間 */
  completed_at?: string;
}

